import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Fingerprint, ShieldCheck } from 'lucide-react';
import GoldButton from '../../components/ui/GoldButton';

const BiometricGate = ({ onAccessGranted }) => {
  const [status, setStatus] = useState('idle'); // idle, scanning, granted

  const startScan = () => {
    setStatus('scanning');
    setTimeout(() => setStatus('granted'), 2500);
    setTimeout(() => onAccessGranted(), 3500);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center">
      <AnimatePresence>
        {status !== 'granted' ? (
          <motion.div 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="text-center"
          >
            <div className="relative inline-block mb-8">
              {/* Pulsing Outer Ring */}
              <motion.div 
                animate={{ scale: [1, 1.2, 1], opacity: [0.2, 0.5, 0.2] }}
                transition={{ duration: 2, repeat: Infinity }}
                className="absolute inset-0 border-2 border-[#D4AF37] rounded-full"
              />
              <div className="p-8 border border-white/10 rounded-full bg-card backdrop-blur-xl">
                <Fingerprint className={`w-16 h-16 ${status === 'scanning' ? 'text-[#D4AF37]' : 'text-white/20'} transition-colors duration-500`} />
              </div>
              
              {/* Scanning Laser Line */}
              {status === 'scanning' && (
                <motion.div 
                  initial={{ top: '0%' }} animate={{ top: '100%' }}
                  transition={{ duration: 1.5, repeat: Infinity, ease: "linear" }}
                  className="absolute left-0 right-0 h-1 bg-[#D4AF37] shadow-[0_0_15px_#D4AF37] z-20"
                />
              )}
            </div>

            <h2 className="font-serif text-2xl tracking-[0.4em] mb-2">IDENTITY VERIFICATION</h2>
            <p className="text-[10px] text-white/40 tracking-widest uppercase mb-12">
              {status === 'scanning' ? 'Analyzing Neural Patterns...' : 'Awaiting Sovereign Credentials'}
            </p>

            {status === 'idle' && (
              <GoldButton onClick={startScan} variant="outline">Initiate Scan</GoldButton>
            )}
          </motion.div>
        ) : (
          <motion.div 
            initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}
            className="text-center"
          >
            <ShieldCheck className="w-20 h-20 text-[#D4AF37] mx-auto mb-6" />
            <h2 className="font-serif text-3xl gold-text tracking-[0.5em]">ACCESS GRANTED</h2>
            <p className="text-[10px] text-white/60 tracking-widest mt-4">Welcome back, Architect.</p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default BiometricGate;
