import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useSovereign } from '../../context/SovereignContext';
import { Play, Pause, RotateCcw, Volume2, VolumeX, zap } from 'lucide-react';
import GoldButton from '../../components/ui/GoldButton';

const FOCUS_MODES = [
  { label: 'TACTICAL', mins: 25, reward: 50 },
  { label: 'STRATEGIC', mins: 45, reward: 100 },
  { label: 'SOVEREIGN', mins: 60, reward: 200 }
];

const FocusEngine = () => {
  const { awardCoins } = useSovereign();
  const [mode, setMode] = useState(FOCUS_MODES[0]);
  const [timeLeft, setTimeLeft] = useState(mode.mins * 60);
  const [isActive, setIsActive] = useState(false);
  const [isAudioOn, setIsAudioOn] = useState(false);
  const audioRef = useRef(null);

  // Timer Logic
  useEffect(() => {
    let interval = null;
    if (isActive && timeLeft > 0) {
      interval = setInterval(() => setTimeLeft(t => t - 1), 1000);
    } else if (timeLeft === 0) {
      clearInterval(interval);
      handleProtocolComplete();
    }
    return () => clearInterval(interval);
  }, [isActive, timeLeft]);

  const handleProtocolComplete = () => {
    setIsActive(false);
    awardCoins(mode.reward);
    // Play success chime here
    alert(`PROTOCOL COMPLETE. ${mode.reward} SOVEREIGN COINS ACQUIRED.`);
    resetTimer();
  };

  const resetTimer = () => {
    setIsActive(false);
    setTimeLeft(mode.mins * 60);
  };

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="max-w-4xl mx-auto p-12 flex flex-col items-center justify-center min-h-[70vh]">
      <div className="text-center mb-16">
        <h2 className="font-serif text-3xl tracking-[0.5em] mb-4">DEEP FOCUS PROTOCOL</h2>
        <div className="flex gap-4 justify-center">
          {FOCUS_MODES.map(f => (
            <button 
              key={f.label}
              onClick={() => { setMode(f); setTimeLeft(f.mins * 60); setIsActive(false); }}
              className={`px-4 py-1 text-[8px] tracking-[0.3em] border transition-all ${mode.label === f.label ? 'border-gold text-gold bg-gold/5' : 'border-white/10 text-white/40'}`}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* The Halo Timer */}
      <div className="relative w-80 h-80 flex items-center justify-center mb-16">
        <svg className="absolute inset-0 w-full h-full -rotate-90">
          <circle cx="160" cy="160" r="150" fill="transparent" stroke="rgba(255,255,255,0.05)" strokeWidth="2" />
          <motion.circle 
            cx="160" cy="160" r="150" fill="transparent" stroke="#D4AF37" strokeWidth="2"
            strokeDasharray="942"
            animate={{ strokeDashoffset: 942 - (942 * (timeLeft / (mode.mins * 60))) }}
            transition={{ duration: 1, ease: "linear" }}
          />
        </svg>

        <div className="text-center z-10">
          <motion.div 
            key={timeLeft}
            initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }}
            className="text-7xl font-mono font-bold tracking-tighter text-white mb-2"
          >
            {formatTime(timeLeft)}
          </motion.div>
          <p className="text-[10px] text-white/30 tracking-[0.4em] uppercase">Remaining Duration</p>
        </div>

        {/* Ambient Pulsing Glow */}
        {isActive && (
          <motion.div 
            animate={{ opacity: [0.1, 0.3, 0.1], scale: [1, 1.05, 1] }}
            transition={{ duration: 4, repeat: Infinity }}
            className="absolute inset-0 bg-gold/10 rounded-full blur-3xl -z-10"
          />
        )}
      </div>

      <div className="flex items-center gap-8">
        <button onClick={() => setIsAudioOn(!isAudioOn)} className="text-white/40 hover:text-gold transition-colors">
          {isAudioOn ? <Volume2 /> : <VolumeX />}
        </button>
        
        <GoldButton onClick={() => setIsActive(!isActive)}>
          {isActive ? <Pause className="inline mr-2 w-4 h-4" /> : <Play className="inline mr-2 w-4 h-4" />}
          {isActive ? 'Suspend' : 'Initiate'}
        </GoldButton>

        <button onClick={resetTimer} className="text-white/40 hover:text-white transition-colors">
          <RotateCcw />
        </button>
      </div>

      {/* Hidden Audio Element for Binaural Beats */}
      <audio 
        ref={audioRef} 
        loop 
        src="https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3" // Replace with elite ambient/binaural track
      />
      {isAudioOn && isActive && <p className="mt-8 text-[8px] text-gold tracking-widest animate-pulse">BINAURAL IMMERSION ACTIVE</p>}
    </div>
  );
};

export default FocusEngine;
