import React, { createContext, useContext, useState, useEffect } from 'react';

const SovereignContext = createContext();

export const SovereignProvider = ({ children }) => {
  const [coins, setCoins] = useState(() => Number(localStorage.getItem('pc_coins')) || 500);
  const [rank, setRank] = useState('NOVICE');
  const [unlockedItems, setUnlockedItems] = useState(() => JSON.parse(localStorage.getItem('pc_vault')) || []);

  useEffect(() => {
    localStorage.setItem('pc_coins', coins);
    localStorage.setItem('pc_vault', JSON.stringify(unlockedItems));
    
    // Auto-calculate Rank
    if (coins >= 2000) setRank('SOVEREIGN');
    else if (coins >= 1000) setRank('ARCHITECT');
    else setRank('STRATEGIST');
  }, [coins, unlockedItems]);

  const awardCoins = (amount) => setCoins(prev => prev + amount);
  const spendCoins = (amount) => {
    if (coins >= amount) {
      setCoins(prev => prev - amount);
      return true;
    }
    return false;
  };

  return (
    <SovereignContext.Provider value={{ coins, rank, unlockedItems, awardCoins, spendCoins, setUnlockedItems }}>
      {children}
    </SovereignContext.Provider>
  );
};

export const useSovereign = () => useContext(SovereignContext);
