import React from 'react';
import { motion } from 'framer-motion';

const GoldButton = ({ children, onClick, variant = 'solid' }) => {
  const isSolid = variant === 'solid';
  
  return (
    <motion.button
      whileHover={{ scale: 1.02, boxShadow: "0px 0px 20px rgba(212, 175, 55, 0.4)" }}
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
      className={`
        relative px-8 py-3 font-serif text-[10px] tracking-[0.3em] uppercase font-bold transition-all
        ${isSolid 
          ? 'bg-gradient-to-r from-[#F3E5AB] via-[#D4AF37] to-[#AA771C] text-black' 
          : 'border border-[#D4AF37] text-[#D4AF37] hover:bg-[#D4AF37]/5'}
      `}
    >
      {children}
    </motion.button>
  );
};

export default GoldButton;
